class LSMTree {
    constructor() { this.memtable = {}; this.sstables = []; }
    put(key, val) { this.memtable[key] = val; if (Object.keys(this.memtable).length >= 3) { this.sstables.push(Object.entries(this.memtable).sort()); this.memtable = {}; } }
    get(key) { if (key in this.memtable) return this.memtable[key]; for (let i = this.sstables.length - 1; i >= 0; i--) { for (let [k, v] of this.sstables[i]) { if (k === key) return v; } } return null; }
}

class BTreeIndex {
    constructor() { this.root = { keys: [], values: [] }; }
    put(key, val) { this.root.keys.push(key); this.root.values.push(val); }
    get(key) { let idx = this.root.keys.indexOf(key); return idx !== -1 ? this.root.values[idx] : null; }
}

class RaftReplica {
    constructor(id) { this.id = id; this.term = 0; this.state = 'Follower'; }
    requestVote(term, candidateId) { if (term > this.term) { this.term = term; this.state = 'Follower'; return true; } return false; }
}

class Coordinator2PC {
    constructor(participants) { this.participants = participants; }
    commitTx(txId) { if (this.participants.every(p => p.prepare(txId))) { this.participants.forEach(p => p.commit(txId)); return 'Committed'; } this.participants.forEach(p => p.abort(txId)); return 'Aborted'; }
}

const crypto = require('crypto');
class HashRouter {
    constructor(nodes = 3) { this.nodes = Array.from({length: nodes}, (_, i) => `Node-${i}`); }
    route(key) { let hash = crypto.createHash('md5').update(key).digest('hex'); return this.nodes[parseInt(hash.substring(0, 8), 16) % this.nodes.length]; }
}

class RangeRouter {
    constructor() { this.boundaries = [['A', 'M', 'Node-0'], ['N', 'Z', 'Node-1']]; }
    route(key) { let c = key[0].toUpperCase(); for (let [s, e, n] of this.boundaries) { if (c >= s && c <= e) return n; } return 'Node-Fallback'; }
}

class ProtobufEncoder {
    static encodeField(tag, valType, value) { let h = (tag << 3) | valType; return Buffer.concat([Buffer.from([h]), Buffer.from(String(value))]); }
}

class AvroEncoder {
    constructor(schema) { this.schema = schema; }
    encode(record) { return Buffer.concat(this.schema.map(([f, t]) => Buffer.from(String(record[f])))); }
}

class SingleLeaderDB {
    constructor() { this.leader = {}; this.replicas = [{}, {}]; }
    write(key, val, client) { this.leader[key] = [val, client]; this.replicas.forEach(r => r[key] = [val, client]); }
    read(key, client, raw = false) { return raw ? (this.leader[key] ? this.leader[key][0] : null) : (this.replicas[0][key] ? this.replicas[0][key][0] : null); }
}

class LeaderlessQuorum {
    constructor(n=3, r=2, w=2) { this.nodes = Array.from({length: n}, () => ({store: {}, ver: {}})); this.r = r; this.w = w; }
    write(key, val) { let v = 1; this.nodes.forEach(n => { n.store[key] = val; n.ver[key] = v; }); }
    read(key) { return this.nodes[0].store[key]; }
}

